// ../../packages/wodal/dist/targets/microbit-v2/rehearsal/tile-docs.js
function microBitV2TileDocs() {
  const docs = pairTileDocs(MICROBIT_V2_TILE_DOC_CONTENT, MICROBIT_V2_TILE_DOCS);
  const unresolved = MICROBIT_V2_TILE_DOCS.filter((entry) => !docs.has(entry.tileId)).map((entry) => entry.contentKey);
  const unmapped = Object.keys(MICROBIT_V2_TILE_DOC_CONTENT).filter((key) => !MICROBIT_V2_TILE_DOCS.some((entry) => entry.contentKey === key));
  if (unresolved.length > 0 || unmapped.length > 0) {
    throw new Error(`the shipped tile documentation does not pair with the tile doc manifest: ${unresolved.length} entries name no content (${unresolved.join(", ")}), ${unmapped.length} files are named by no entry (${unmapped.join(", ")})`);
  }
  return docs;
}

